import os
import shutil
import uuid
from datetime import datetime

# Constants
BACKUP_DIR = '/tmp/backup'


def get_unique_backup_dir():
    os.makedirs(BACKUP_DIR, exist_ok=True)
    while True:
        stamp = datetime.utcnow().strftime("%Y%m%d%H%M%S_%f")
        candidate = os.path.join(BACKUP_DIR, f"backup_{stamp}_{uuid.uuid4().hex}")
        if not os.path.exists(candidate):
            return candidate


def task_func(directory):
    """
    Create a backup of `directory` and then clean the directory contents.

    Returns:
        tuple[str, list]: (backup_directory_path, errors)
    """
    if not os.path.isdir(directory):
        return "", [f"Directory does not exist or is not a directory: {directory}"]

    errors = []

    try:
        backup_dir = get_unique_backup_dir()
    except Exception as e:
        return "", [f"Could not prepare backup directory: {e}"]

    try:
        shutil.copytree(directory, backup_dir)
    except FileExistsError:
        # Extremely unlikely due to unique path generation; retry a few times.
        for _ in range(5):
            try:
                backup_dir = get_unique_backup_dir()
                shutil.copytree(directory, backup_dir)
                break
            except FileExistsError:
                continue
            except Exception as e:
                try:
                    if os.path.exists(backup_dir):
                        shutil.rmtree(backup_dir)
                except Exception as cleanup_err:
                    errors.append(f"Failed to remove incomplete backup {backup_dir}: {cleanup_err}")
                return backup_dir, [f"Backup failed: {e}"] + errors
        else:
            return backup_dir, ["Backup failed: could not create a unique backup directory."]
    except Exception as e:
        try:
            if os.path.exists(backup_dir):
                shutil.rmtree(backup_dir)
        except Exception as cleanup_err:
            errors.append(f"Failed to remove incomplete backup {backup_dir}: {cleanup_err}")
        return backup_dir, [f"Backup failed: {e}"] + errors

    # Clean the directory afterwards (preserve the directory itself).
    try:
        for name in os.listdir(directory):
            path = os.path.join(directory, name)
            try:
                if os.path.islink(path) or os.path.isfile(path):
                    os.unlink(path)
                elif os.path.isdir(path):
                    shutil.rmtree(path)
                else:
                    os.unlink(path)
            except Exception as e:
                errors.append(f"Failed to remove {path}: {e}")
    except Exception as e:
        errors.append(f"Failed to list directory for cleanup: {e}")

    return backup_dir, errors

