import nltk
from string import punctuation
import seaborn as sns
import matplotlib.pyplot as plt

# Constants
PUNCTUATION = set(punctuation)


def task_func(text):
    if not text:
        return None

    try:
        tokens = nltk.word_tokenize(text)
    except LookupError:
        tokens = text.split()

    freq = {}
    for token in tokens:
        if token.startswith("$") and any(ch not in PUNCTUATION for ch in token):
            freq[token] = freq.get(token, 0) + 1

    if not freq:
        return None

    words = list(freq.keys())
    counts = [freq[word] for word in words]

    fig, ax = plt.subplots()
    sns.barplot(x=words, y=counts, ax=ax)
    ax.set_xlabel("Words")
    ax.set_ylabel("Frequencies")
    return ax

