import subprocess
import os
import shutil
from glob import glob

def task_func(src_folder, dst_folder):
    result = {
        "success": False,
        "message": "",
        "failed_files": [],
    }

    def mark_failed(name):
        if name not in result["failed_files"]:
            result["failed_files"].append(name)

    try:
        if not os.path.isdir(src_folder):
            result["message"] = f"Source folder does not exist or is not a directory: {src_folder}"
            return result

        os.makedirs(dst_folder, exist_ok=True)

        files = [path for path in glob(os.path.join(src_folder, "*")) if os.path.isfile(path)]
        if not files:
            result["success"] = True
            result["message"] = "No files found to compress."
            return result

        processes = []

        for src_path in files:
            filename = os.path.basename(src_path)
            dst_path = os.path.join(dst_folder, filename + ".gz")

            try:
                with open(dst_path, "wb") as out_handle:
                    proc = subprocess.Popen(
                        ["gzip", "-c", src_path],
                        stdout=out_handle,
                        stderr=subprocess.PIPE,
                    )
                processes.append((filename, src_path, dst_path, proc))
            except Exception:
                mark_failed(filename)
                try:
                    if os.path.exists(dst_path):
                        os.remove(dst_path)
                except OSError:
                    pass

        for filename, src_path, dst_path, proc in processes:
            try:
                _, err = proc.communicate()
                if proc.returncode != 0:
                    mark_failed(filename)
                    try:
                        if os.path.exists(dst_path):
                            os.remove(dst_path)
                    except OSError:
                        pass
                    continue

                try:
                    os.remove(src_path)
                except OSError:
                    mark_failed(filename)
            except Exception:
                mark_failed(filename)
                try:
                    if os.path.exists(dst_path):
                        os.remove(dst_path)
                except OSError:
                    pass

        result["success"] = len(result["failed_files"]) == 0
        if result["success"]:
            result["message"] = (
                f"Successfully compressed and moved {len(files)} file(s) "
                f"from '{src_folder}' to '{dst_folder}'."
            )
        else:
            success_count = len(files) - len(result["failed_files"])
            result["message"] = (
                f"Completed with errors. {success_count} file(s) succeeded, "
                f"{len(result['failed_files'])} file(s) failed."
            )

        return result

    except Exception as exc:
        result["message"] = f"Unexpected error: {exc}"
        return result

