import pandas as pd
import csv
from difflib import ndiff
from io import StringIO


def _read_csv_as_lines(file_path, delimiter=',', quotechar='"'):
    try:
        with open(file_path, "r", newline="", encoding="utf-8") as handle:
            reader = csv.reader(handle, delimiter=delimiter, quotechar=quotechar)
            lines = []
            for row in reader:
                buffer = StringIO()
                writer = csv.writer(
                    buffer,
                    delimiter=delimiter,
                    quotechar=quotechar,
                    lineterminator=""
                )
                writer.writerow(row)
                lines.append(buffer.getvalue())
            return lines
    except FileNotFoundError:
        raise
    except Exception as exc:
        raise Exception(str(exc)) from exc


def task_func(file_path1, file_path2, delimiter=',', quotechar='"'):
    lines1 = _read_csv_as_lines(file_path1, delimiter=delimiter, quotechar=quotechar)
    lines2 = _read_csv_as_lines(file_path2, delimiter=delimiter, quotechar=quotechar)

    if not any(line.strip() for line in lines1) or not any(line.strip() for line in lines2):
        raise ValueError("One or both files are empty.")

    records = []
    line_no1 = 0
    line_no2 = 0

    for diff_line in ndiff(lines1, lines2):
        tag = diff_line[:2]
        content = diff_line[2:]

        if tag == "  ":
            line_no1 += 1
            line_no2 += 1
            records.append({
                "Line Number": line_no1,
                "Status": " ",
                "Content": content
            })
        elif tag == "- ":
            line_no1 += 1
            records.append({
                "Line Number": line_no1,
                "Status": "-",
                "Content": content
            })
        elif tag == "+ ":
            line_no2 += 1
            records.append({
                "Line Number": line_no2,
                "Status": "+",
                "Content": content
            })
        else:
            # Ignore ndiff intraline markers ("? ")
            continue

    return pd.DataFrame(records, columns=["Line Number", "Status", "Content"])

