import pandas as pd
import matplotlib.pyplot as plt
from typing import Any, List
import numpy as np


def task_func(data_dict):
    def _extract_df(obj: Any) -> pd.DataFrame:
        if isinstance(obj, pd.DataFrame):
            return obj

        if isinstance(obj, dict):
            for key in ("dataframe", "df", "data", "table"):
                value = obj.get(key)
                if isinstance(value, pd.DataFrame):
                    return value
            for value in obj.values():
                if isinstance(value, pd.DataFrame):
                    return value

        return pd.DataFrame(obj)

    def _is_uniform(series: pd.Series) -> bool:
        s = series.dropna()
        if s.empty or s.nunique(dropna=True) <= 1:
            return True

        if pd.api.types.is_datetime64_any_dtype(s):
            values = pd.to_datetime(s, errors="coerce").dropna().astype("int64").to_numpy()
            if values.size <= 1:
                return True
            bins = min(10, max(2, int(np.sqrt(values.size))))
            counts, _ = np.histogram(values, bins=bins)

        elif pd.api.types.is_numeric_dtype(s):
            values = pd.to_numeric(s, errors="coerce").dropna().to_numpy()
            if values.size <= 1 or np.unique(values).size <= 1:
                return True
            bins = min(10, max(2, int(np.sqrt(values.size))))
            counts, _ = np.histogram(values, bins=bins)

        else:
            counts = s.value_counts().to_numpy()

        counts = np.asarray(counts, dtype=float)
        if counts.size <= 1:
            return True

        expected = counts.mean()
        if expected == 0:
            return True

        try:
            from scipy.stats import chi2 as chi2_dist

            chi2_stat = float(((counts - expected) ** 2 / expected).sum())
            p_value = chi2_dist.sf(chi2_stat, df=counts.size - 1)
            return bool(p_value >= 0.05)
        except Exception:
            rel_dev = np.abs(counts - expected) / expected
            return bool(np.max(rel_dev) <= 0.25)

    df = _extract_df(data_dict)

    if df.empty:
        fig, ax = plt.subplots(figsize=(6, 4))
        ax.set_axis_off()
        return [ax]

    n_cols = len(df.columns)
    fig, axes = plt.subplots(n_cols, 1, figsize=(8, max(3, 3 * n_cols)), squeeze=False)
    axes_list = []

    for i, col in enumerate(df.columns):
        ax = axes[i, 0]
        axes_list.append(ax)

        series = df[col]
        non_null = series.dropna()

        if non_null.empty:
            ax.set_title(f"Histogram of {col}")
            ax.text(0.5, 0.5, "No data", ha="center", va="center", transform=ax.transAxes)
            ax.set_xlabel(str(col))
            ax.set_ylabel("Frequency")
            continue

        if pd.api.types.is_numeric_dtype(non_null):
            values = pd.to_numeric(non_null, errors="coerce").dropna().to_numpy()
            if values.size == 0:
                ax.text(
                    0.5,
                    0.5,
                    "No plottable data",
                    ha="center",
                    va="center",
                    transform=ax.transAxes,
                )
            else:
                bins = min(10, max(1, int(np.sqrt(values.size))))
                ax.hist(values, bins=bins, edgecolor="black")

        elif pd.api.types.is_datetime64_any_dtype(non_null):
            values = pd.to_datetime(non_null, errors="coerce").dropna().astype("int64").to_numpy()
            if values.size == 0:
                ax.text(
                    0.5,
                    0.5,
                    "No plottable data",
                    ha="center",
                    va="center",
                    transform=ax.transAxes,
                )
            else:
                bins = min(10, max(1, int(np.sqrt(values.size))))
                ax.hist(values, bins=bins, edgecolor="black")

        else:
            codes, uniques = pd.factorize(non_null.astype(str), sort=False)
            bins = max(1, len(uniques))
            ax.hist(codes, bins=bins, edgecolor="black", align="left", rwidth=0.8)
            ax.set_xticks(range(len(uniques)))
            ax.set_xticklabels(uniques, rotation=45, ha="right")

        ax.set_title(f"Histogram of {col}")
        ax.set_xlabel(str(col))
        ax.set_ylabel("Frequency")

        if not _is_uniform(series):
            print(f"Column '{col}' does not appear to have a uniform distribution.")

    fig.tight_layout()
    return axes_list

